  double div=divergence(time),seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();std::ofstream stats(out/"statistics.json");stats<<std::setprecision(12)<<"{\"steps\":"<<steps<<",\"rejected_steps\":"<<rejected<<",\"first_order_fallback_steps\":"<<fallback_steps<<",\"minimum_dt_day\":"<<mindt<<",\"wall_seconds\":"<<seconds<<",\"mean_dimensionless_divB\":"<<div<<",\"max_dimensionless_divB\":"<<maxdiv<<",\"weighted_dimensionless_divB\":"<<weighted_div<<",\"estimated_allocated_MB\":"<<(total*(8*sizeof(A)+3*sizeof(Face)+sizeof(double))/1e6)<<"}\n";unsigned long long counts[5];for(int a=0;a<5;++a)counts[a]=hll_cpu_counts[a].load();write_hlld_report(out,day_hist,counts);std::cerr<<"Finished: "<<steps<<" steps, "<<seconds<<" s, rejected="<<rejected<<", first_order_fallbacks="<<fallback_steps<<", mean_h_divB/B="<<div<<", max="<<maxdiv<<"\n";
 }
};

// Same numerical flux and RK update on a Cartesian tube for the canonical
// Brio-Wu problem; first-order spatial form isolates flux/energy/positivity.
void brio_wu(const std::string&dir,int n=400){if(n<20||n>20000)throw std::runtime_error("Brio-Wu n outside20..20000");fs::create_directories(dir);double g=2,dx=1./n,t=0;std::vector<A>u(n),v(n),rhs(n),pr(n);for(int i=0;i<n;++i){A p={};p[0]=i<n/2?1:.125;p[4]=i<n/2?1:.1;p[5]=.75;p[6]=i<n/2?1:-1;u[i]=conserved(p,g);}int steps=0;while(t<.1-1e-13){double a=0;for(int i=0;i<n;++i){if(!primitive(u[i],pr[i],g))throw std::runtime_error("Brio-Wu positivity");a=std::max(a,std::abs(pr[i][1])+fast(pr[i],{1,0,0},g));}double h=std::min(.35*dx/a,.1-t);auto calc=[&](const std::vector<A>&s){std::vector<A>p(n),f(n+1);for(int i=0;i<n;++i)if(!primitive(s[i],p[i],g))throw std::runtime_error("Brio-Wu RK positivity");for(int i=0;i<=n;++i)f[i]=riemann(p[std::max(i-1,0)],p[std::min(i,n-1)],{1,0,0},1,g,a);for(int i=0;i<n;++i)for(int k=0;k<NV;++k)rhs[i][k]=-(f[i+1][k]-f[i][k])/dx;};calc(u);for(int i=0;i<n;++i)for(int k=0;k<NV;++k)v[i][k]=u[i][k]+h*rhs[i][k];calc(v);for(int i=0;i<n;++i)for(int k=0;k<NV;++k)u[i][k]=.5*(u[i][k]+v[i][k]+h*rhs[i][k]);t+=h;++steps;}
 std::ofstream f(fs::path(dir)/"brio_wu.csv");f<<"x,rho,vx,vy,p,Bx,By\n";double errorbx=0;for(int i=0;i<n;++i){A p;if(!primitive(u[i],p,g))throw std::runtime_error("Brio-Wu final positivity");errorbx=std::max(errorbx,std::abs(p[5]-.75));f<<(i+.5)*dx<<','<<p[0]<<','<<p[1]<<','<<p[2]<<','<<p[4]<<','<<p[5]<<','<<p[6]<<'\n';}if(errorbx>1e-12)throw std::runtime_error("Brio-Wu normal field drift");unsigned long long counts[5];for(int a=0;a<5;++a)counts[a]=hll_cpu_counts[a].load();write_hlld_report(dir,{},counts);std::cout<<"Brio-Wu completed: steps="<<steps<<", max_Bx_error="<<errorbx<<"\n";
}
int main(int argc,char**argv){try{if(argc>=3&&std::string(argv[1])=="--test"&&std::string(argv[2])=="brio-wu"){brio_wu(argc>3?argv[3]:"brio_wu_output",argc>4?std::stoi(argv[4]):400);return 0;}if(argc!=3||std::string(argv[1])!="--config"){std::cerr<<"Usage: mhd_solver --config run.cfg | --test brio-wu [output_dir] [n]\n";return 2;}Config c(argv[2]);
 #ifdef _OPENMP
 omp_set_num_threads(std::clamp(c.i("threads",2),1,2));
 #endif
 Solver s(c);s.run();return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
"}

